import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostBinding,
  HostListener,
  Input,
  OnChanges,
  SimpleChanges,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  numberAttribute,
} from '@angular/core';

import { ObserversModule } from '@angular/cdk/observers';
import {
  QDestroyService,
  QSharedResizeObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';
import { QListItemRightColumnAlignment } from '../types/list-item-column-alignment.type';
import { QListItemDensity } from '../types/list-item-density.type';
import { QListItemIconPosition } from '../types/list-item-icon-position.type';
import { QListItemRowGap } from '../types/list-item-row-gap.type';
import { QListItemVariant } from '../types/list-item-variant.type';

const leftColumnWidthLabel = '_leftColumnWidth';
const rightColumnWidthLabel = '_rightColumnWidth';
type QColumnWidths = typeof rightColumnWidthLabel | typeof leftColumnWidthLabel;

@Component({
  selector:
    'li[q-list-item], li[qListItem], a[q-nav-list-item], a[qNavListItem], button[q-nav-list-item], button[qNavListItem]',
  templateUrl: './list-item.component.html',
  styleUrls: ['./list-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [ObserversModule],
  providers: [QDestroyService],
})
export class QListItemComponent implements AfterViewInit, OnChanges {
  @Input() variant: QListItemVariant = 'primary';
  @Input() density: QListItemDensity = 'default';
  @Input() rightColumnAlignment: QListItemRightColumnAlignment = 'left';
  @Input() interactiveIconPosition: QListItemIconPosition = 'center';
  /**
   * @deprecated Use `--awds-list-item-row-gap` token instead.
   * @breaking-change First major after 13 Aug 2026
   */
  @Input({ transform: numberAttribute }) rowGap: QListItemRowGap = 4;
  @Input({ transform: booleanAttribute }) done = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-list-item';
  @Input() @HostBinding('attr.disabled') disabled: boolean | null = null;

  @Input() set leftColumnWidth(value: number | string) {
    this._updateColumnWidth(value, leftColumnWidthLabel);
  }
  get leftColumnWidth(): string {
    return this[leftColumnWidthLabel];
  }

  @Input() set rightColumnWidth(value: number | string) {
    this._updateColumnWidth(value, rightColumnWidthLabel);
  }
  get rightColumnWidth(): string {
    return this[rightColumnWidthLabel];
  }

  @Input() @HostBinding('attr.tabindex') get tabIndex(): number {
    return this.disabled ? -1 : this._tabIndex;
  }
  set tabIndex(value: number) {
    this._tabIndex = value;
  }

  @HostBinding('class') get hostClassNames(): string {
    return [
      'q-list-item',
      'q-focus-indicator-inset',
      `q-list-item-${this.done ? 'done' : ''}`,
      `q-list-item-${this.rightColumnAlignment}`,
      `q-list-item-${this.density}`,
      `q-list-item-${this.variant}`,
      `q-list-item-icon-${this.interactiveIconPosition}`,
      this._pressed ? 'q-list-item-pressed' : '',
    ].join(' ');
  }

  @HostListener('keydown', ['$event']) _onKeyDown(event: Event): void {
    if (!(event instanceof KeyboardEvent)) return;
    if (this.disabled) return;

    if ([SPACE, ENTER].includes(event.code)) {
      this._pressed = true;
      event.stopPropagation();
      event.preventDefault();
    }
  }

  @HostListener('keyup', ['$event']) _onKeyUp(event: Event): void {
    if (!(event instanceof KeyboardEvent)) return;
    if (this.disabled) return;

    if ([SPACE, ENTER].includes(event.code)) {
      this._pressed = false;
      this._elementRef.nativeElement.click();
      event.stopPropagation();
      event.preventDefault();
    }
  }

  private [leftColumnWidthLabel] = 'auto';
  private [rightColumnWidthLabel] = 'auto';
  private _pressed = false;
  private _tabIndex = 0;
  private _leftRows: HTMLElement[] = [];
  private _rightRows: HTMLElement[] = [];
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private readonly _elementRef = inject(ElementRef);
  private readonly _sharedResizeObserverService = inject(QSharedResizeObserverService);
  private readonly _destroy$ = inject(QDestroyService);

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['rowGap']) {
      //TODO: Remove this once the deprecated input is removed
      this._elementRef.nativeElement.style.setProperty(
        '--awds-list-item-row-gap',
        `${this.rowGap}px`,
      );
    }
  }

  ngAfterViewInit(): void {
    this._setupResizeObserver();
    this._setRows();
    this._adjustRowsMinHeight();
  }

  _onContentChange(): void {
    this._setRows();
    this._removeRowsMinHeight();
    this._adjustRowsMinHeight();
  }

  private _updateColumnWidth(value: string | number, column: QColumnWidths): void {
    if (isNaN(Number(value.toString()))) {
      this[column] = value as string;
    } else {
      this[column] = `${value}px`;
    }
    this._changeDetectorRef.markForCheck();
  }

  private _setRows(): void {
    this._leftRows = Array.from(this._elementRef.nativeElement.querySelectorAll('[leftcolumn]'));
    this._rightRows = Array.from(this._elementRef.nativeElement.querySelectorAll('[rightcolumn]'));
  }

  private _adjustRowsMinHeight(): void {
    if (this._leftRows.length && this._rightRows.length) {
      const rowsLength = Math.max(this._leftRows.length, this._rightRows.length);

      for (let index = 0; index < rowsLength; index++) {
        const leftRowHeight = this._leftRows[index]?.offsetHeight ?? 0;
        const rightRowHeight = this._rightRows[index]?.offsetHeight ?? 0;

        if (leftRowHeight > rightRowHeight) {
          this._setMinHeightStyle(this._rightRows[index], leftRowHeight);
        } else if (rightRowHeight > leftRowHeight)
          this._setMinHeightStyle(this._leftRows[index], rightRowHeight);
      }
    }
  }

  private _removeRowsMinHeight(): void {
    if (this._leftRows.length || this._rightRows.length) {
      const rows = [...this._leftRows, ...this._rightRows];

      for (const row of rows) {
        this._removeMinHeightStyle(row);
      }
    }
  }

  private _setMinHeightStyle(row: HTMLElement, minHeight: number): void {
    if (!row) {
      return;
    }

    row.style.setProperty('min-height', `${minHeight}px`);
  }

  private _removeMinHeightStyle(row: HTMLElement): void {
    if (!row) {
      return;
    }

    if (row.style.minHeight) {
      row.style.removeProperty('min-height');
    }
  }

  private _setupResizeObserver(): void {
    this._sharedResizeObserverService
      .observe(this._elementRef.nativeElement)
      ?.pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        this._removeRowsMinHeight();
        this._adjustRowsMinHeight();
      });
  }
}
