import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  selector: 'ul[q-list], ul[qList], ol[q-list], ol[qList], nav[q-nav-list], nav[qNavList]',
  template: `<ng-content />`,
  styleUrls: ['./list.component.scss'],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QListComponent {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-list';
  @Input({ transform: booleanAttribute }) inset = false;

  @HostBinding('class') get hostClassNames(): string {
    return ['q-list', this.inset ? 'q-list-inset' : ''].join(' ');
  }
}
